import React from 'react';
import { Container, Row, Col, Table } from 'reactstrap';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip, Legend, BarChart, CartesianGrid, XAxis, YAxis, Bar } from 'recharts';
import useFetch from '../../hooks/useFetch';
import { BASE_URL } from '../../utils/config';

const Dashboard = () => {
   const { data: bookings, loading, error } = useFetch(`${BASE_URL}/booking`);

   const totalBookings = bookings?.length || 0;
   const totalRevenue = bookings?.reduce((sum, item) => {
      return item.status === 'Đã thanh toán' ? sum + (item.totalPrice || 0) : sum;
   }, 0) || 0;
   const canceledBookings = bookings?.filter(item => item.status === 'Đã hủy' || item.status === 'cancelled').length || 0;
   const cancelRate = totalBookings ? Math.round((canceledBookings / totalBookings) * 100) : 0;

   const statusSummary = bookings?.reduce((summary, item) => {
      const status = item.status || 'Chưa xử lý';
      summary[status] = (summary[status] || 0) + 1;
      return summary;
   }, {}) || {};

   const revenueByStatus = bookings?.reduce((summary, item) => {
      const status = item.status || 'Chưa xử lý';
      summary[status] = (summary[status] || 0) + (item.totalPrice || 0);
      return summary;
   }, {}) || {};

   const statusCountData = Object.entries(statusSummary).map(([status, count]) => ({ status, count }));
   const revenueStatusData = Object.entries(revenueByStatus).map(([status, value]) => ({ status, value }));
   const chartColors = ['#2f80ed', '#27ae60', '#f2c94c', '#eb5757', '#9b51e0', '#56ccf2'];

   return (
      <section className='mt-5 mb-5'>
         <Container>
            <Row>
               <Col lg='12' className='mb-4'>
                  <h2 className='text-primary fw-bold'>Bảng điều khiển Admin</h2>
                  <p className='text-muted'>Tổng quan đơn hàng và doanh thu hệ thống.</p>
               </Col>

               <Col lg='4' md='6' className='mb-3'>
                  <div className='p-4 bg-white rounded shadow-sm'>
                     <h5 className='mb-3'>Tổng booking</h5>
                     <h3>{totalBookings}</h3>
                  </div>
               </Col>
               <Col lg='4' md='6' className='mb-3'>
                  <div className='p-4 bg-white rounded shadow-sm'>
                     <h5 className='mb-3'>Doanh thu</h5>
                     <h3>{totalRevenue.toLocaleString('vi-VN')} đ</h3>
                  </div>
               </Col>
               <Col lg='4' md='6' className='mb-3'>
                  <div className='p-4 bg-white rounded shadow-sm'>
                     <h5 className='mb-3'>Hủy đặt</h5>
                     <h3>{canceledBookings} ({cancelRate}%)</h3>
                  </div>
               </Col>

               <Col lg='12' className='mt-4'>
                  <div className='bg-white rounded shadow-sm p-4 mb-4'>
                     <h5 className='mb-4'>Tổng quan trạng thái booking</h5>
                     <div style={{ width: '100%', height: 320 }}>
                        <ResponsiveContainer width='100%' height='100%'>
                           <BarChart data={statusCountData} margin={{ top: 20, right: 20, left: 0, bottom: 20 }}>
                              <CartesianGrid strokeDasharray='3 3' />
                              <XAxis dataKey='status' tick={{ fontSize: 12 }} />
                              <YAxis />
                              <Tooltip />
                              <Bar dataKey='count' fill='#2f80ed' />
                           </BarChart>
                        </ResponsiveContainer>
                     </div>
                  </div>
               </Col>

               <Col lg='12' className='mb-4'>
                  <div className='bg-white rounded shadow-sm p-4'>
                     <h5 className='mb-4'>Doanh thu theo trạng thái</h5>
                     <div style={{ width: '100%', height: 320 }}>
                        <ResponsiveContainer width='100%' height='100%'>
                           <PieChart>
                              <Pie
                                 data={revenueStatusData}
                                 dataKey='value'
                                 nameKey='status'
                                 cx='50%'
                                 cy='50%'
                                 outerRadius={110}
                                 fill='#8884d8'
                                 label={(entry) => entry.status}
                              >
                                 {revenueStatusData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={chartColors[index % chartColors.length]} />
                                 ))}
                              </Pie>
                              <Tooltip formatter={(value) => new Intl.NumberFormat('vi-VN').format(value) + ' đ'} />
                              <Legend verticalAlign='bottom' height={36} />
                           </PieChart>
                        </ResponsiveContainer>
                     </div>
                  </div>
               </Col>

               <Col lg='12' className='mt-4'>
                  <div className='bg-white rounded shadow-sm p-4'>
                     <h5 className='mb-4'>Danh sách booking mới</h5>
                     <Table striped responsive>
                        <thead>
                           <tr>
                              <th>Người đặt</th>
                              <th>Tour</th>
                              <th>Ngày</th>
                              <th>Giá</th>
                              <th>Trạng thái</th>
                           </tr>
                        </thead>
                        <tbody>
                           {loading && (
                              <tr>
                                 <td colSpan='5'>Đang tải dữ liệu...</td>
                              </tr>
                           )}
                           {error && (
                              <tr>
                                 <td colSpan='5' className='text-danger'>{error}</td>
                              </tr>
                           )}
                           {!loading && !error && bookings?.map(item => (
                              <tr key={item._id}>
                                 <td>{item.fullName || 'N/A'}</td>
                                 <td>{item.tourName || 'N/A'}</td>
                                 <td>{item.bookingAt ? new Date(item.bookingAt).toLocaleDateString('vi-VN') : 'N/A'}</td>
                                 <td>{Number(item.totalPrice || 0).toLocaleString('vi-VN')} đ</td>
                                 <td>{item.status || 'Chưa xử lý'}</td>
                              </tr>
                           ))}
                        </tbody>
                     </Table>
                  </div>
               </Col>
            </Row>
         </Container>
      </section>
   );
};

export default Dashboard;
